using System;
using System.IO;
using System.Linq;
using System.Text;
using UnityEditor;
using UnityEngine;
using UnityEngine.SceneManagement;
[InitializeOnLoad]
public static class ForestLiveAudit
{
    const string Folder="Backups/Forest_GameView_Redesign_20261102";
    static ForestLiveAudit(){EditorApplication.delayCall+=()=>EditorApplication.update+=Poll;}
    static void Poll(){if(EditorApplication.isCompiling||EditorApplication.isUpdating)return;var path=Folder+"/request.txt";if(!File.Exists(path))return;var cmd=File.ReadAllText(path).Trim();File.Delete(path);try{if(cmd=="audit")Audit();else if(cmd=="enhance")ThachSanhForestEnhancer.Enhance();else if(cmd=="refine")ThachSanhForestEnhancer.RefineMaterials();else if(cmd=="remove")ThachSanhForestEnhancer.Remove();else if(cmd=="capture")Capture();else if(cmd=="verify")ThachSanhForestEnhancer.Verify();else if(cmd=="undo"){Undo.PerformUndo();UnityEditor.SceneManagement.EditorSceneManager.SaveScene(SceneManager.GetActiveScene());Audit();}else if(cmd=="redo"){Undo.PerformRedo();UnityEditor.SceneManagement.EditorSceneManager.SaveScene(SceneManager.GetActiveScene());Audit();}else if(cmd=="stop")EditorApplication.isPlaying=false;else if(cmd=="play")EditorApplication.isPlaying=true;else if(cmd=="begin"){UnityEngine.Object.FindAnyObjectByType<GioiThieuCotTruyen>().BamNutBatDau();EditorApplication.delayCall+=()=>{EditorApplication.isPaused=true;Audit();};}}catch(Exception e){File.WriteAllText(Folder+"/ERROR.txt",e.ToString());Debug.LogException(e);}}
    public static void Audit(){var b=new StringBuilder();b.AppendLine("PROJECT "+Application.dataPath);var scene=SceneManager.GetActiveScene();b.AppendLine("SCENE "+scene.path+" dirty="+scene.isDirty+" playing="+EditorApplication.isPlaying);foreach(var root in scene.GetRootGameObjects()){b.AppendLine("ROOT "+root.name+" pos="+root.transform.position.ToString("F3")+" rot="+root.transform.eulerAngles+" scale="+root.transform.localScale);foreach(var cam in root.GetComponentsInChildren<Camera>(true))b.AppendLine("CAM "+cam.name+" enabled="+cam.enabled+" fov="+cam.fieldOfView+" forward="+cam.transform.forward+" scripts="+string.Join(",",cam.GetComponents<MonoBehaviour>().Select(x=>x?x.GetType().Name:"MISSING")));foreach(var r in root.GetComponentsInChildren<MeshRenderer>())if(root.name=="cayda")b.AppendLine("TREE "+r.name+" bounds="+r.bounds);foreach(var t in root.GetComponentsInChildren<Terrain>()){b.AppendLine("TERRAIN "+AssetDatabase.GetAssetPath(t.terrainData)+" size="+t.terrainData.size);foreach(var d in t.terrainData.detailPrototypes)b.AppendLine("DETAIL prefab="+d.prototype+" texture="+d.prototypeTexture);foreach(var p in t.terrainData.treePrototypes)b.AppendLine("TREETYPE "+AssetDatabase.GetAssetPath(p.prefab));}}
    File.WriteAllText(Folder+"/audit.txt",b.ToString());Capture();}
    public static void Capture(){ShaderUtil.allowAsyncCompilation=false;var scene=SceneManager.GetActiveScene();var cam=scene.GetRootGameObjects().SelectMany(x=>x.GetComponentsInChildren<Camera>()).First(x=>x.name=="Main Camera");var rt=new RenderTexture(1600,900,24,RenderTextureFormat.ARGB32);rt.Create();var old=cam.targetTexture;var active=RenderTexture.active;cam.targetTexture=rt;for(int i=0;i<4;i++)cam.Render();RenderTexture.active=rt;var tex=new Texture2D(1600,900,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,1600,900),0,0);tex.Apply();File.WriteAllBytes(Folder+"/"+(scene.GetRootGameObjects().Any(x=>x.name=="Forest_Environment_Enhancement"&&x.transform.Find("GameView_Redesign"))?"after":"before")+(EditorApplication.isPlaying?"_play":"_edit")+".png",tex.EncodeToPNG());cam.targetTexture=old;RenderTexture.active=active;UnityEngine.Object.DestroyImmediate(tex);rt.Release();UnityEngine.Object.DestroyImmediate(rt);}
}
